CREATE TABLE `account_deletion_archives` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '原用户ID',
  `deletion_requested_at` datetime DEFAULT NULL COMMENT '注销申请时间',
  `archived_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '进入历史留存时间',
  `email_enc` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '注销时邮箱密文',
  `email_bidx` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '注销时邮箱盲索引，仅用于留存查询，不参与登录查重',
  `phone_enc` mediumtext COLLATE utf8mb4_unicode_ci COMMENT '注销时手机号密文',
  `phone_bidx` char(64) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '注销时手机号盲索引，仅用于留存查询，不参与登录查重',
  `archive_reason` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GRACE_EXPIRED' COMMENT '归档原因',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted_at` datetime DEFAULT NULL COMMENT '删除时间（软删除）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_account_deletion_archive_user` (`user_id`),
  KEY `idx_account_deletion_archive_email_bidx` (`email_bidx`),
  KEY `idx_account_deletion_archive_phone_bidx` (`phone_bidx`),
  KEY `idx_account_deletion_archive_archived_at` (`archived_at`),
  CONSTRAINT `fk_account_deletion_archive_user_id` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='账号注销历史留存档案';
